INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N083-01','CN0174','W06S02','历史新剂及再生边界','2.1.8.2、2.1.9、2.1-11','历史生活21.7m³/d，COD238、SS54.9、NH3-N18.1、油3.12；旧制水、地洗路径被要求整改，改至拟再生站，不当现行。2016原成本E0001–04已入库，不重复；原RO COD442.9与去除率矛盾保留。截图404。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N083-02','CN0173','W08S01','技改接管定量','表4.4-21 pp108–109','2号站7402.93、1号33574.45、总40977.38m³/a，表列接管浓度，非实际；园区环境外排预测非厂内出水。旧UF回用60%已经入库。截图502。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N083-03','CN0069','S046-02','扩建水站与生活量','同报告政府公开2022版3.2.8.2、依托表','现有150扩建至240m³/d（非新增240、非已建），现有生活约9、新增1.92m³/d。另一公开版本 URL https://sthjt.xinjiang.gov.cn/xjepd/hjyxpjsl/202212/ae54050f64b340c9a9a82c40bf60c657/files/新疆绿园华泰环保科技有限公司催化剂综合利用改扩建项目环境影响报告书-20221228192830585.pdf；截图404；未确认两版其他章节一致。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N083-04','CN0346','S083-01','历史验收范围','一、三、四、七','2020-04-10历史验收，富钛粉、钨酸钠；偏钒酸铵沉钒未运行，办公生活区未建；生产水回用，生活10m³/d；8项监测达标但未公布具体浓度；验收环保投资385万元（环评357），综合口径不入水经济。p3截图成功。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N083-05','CN0347','S083-02','经营台账和工艺','第一部分、表1.2-1','机械裁剪粉碎混匀，外售含贵金属粉至下游提纯；历史2018批2000中1000收贮未开展，实际接收、利用与库存各期分列；原材料2020至2024年10月，无当前生产水证据。雨水图页18.6MB超限。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N083-06','CN0348','S083-03','许可边界','转载正文一','综合经营65000t/a，HW13、17、35、46、48、49、50；2023-07-18至2028-07-17，编号HW6108210003；原件及实际分项待核。非催化剂独占规模。','WEB_SECONDARY','WEB_TEXT','2026-11-28');
